#!/bin/sh
# Generated by FWShift: rows for the packet filter (and NAT) of a Phoenix Contact mGuard, added with gaiconfig.
# Read the report first: what is not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE            prints the gaiconfig calls; runs anywhere
#   sh THIS_FILE                      on the mGuard (SSH, as root or admin): adds the groups and rows
#   FWSHIFT_APPEND=yes sh THIS_FILE   also when the tables have rows: the new ones go after them
#
# Nothing is changed or deleted, and no interface, route or access to the mGuard is touched. Every call but the last
# writes with --silent; the last one reconfigures, and the rows take effect then. A call gaiconfig refuses stops the
# script: what was written before is stored but not active (the groups start with 'fws_', the rows' comments
# with the names of the rules); remove it in the web interface, or run the script again after fixing the cause.
set -u
DRY_RUN="${DRY_RUN:-}"
FWSHIFT_APPEND="${FWSHIFT_APPEND:-}"
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
gc() {
  if [ -n "$DRY_RUN" ]; then printf 'gaiconfig' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gaiconfig "$@" >/dev/null || fail "gaiconfig $*"
}
rows() {
  if [ -n "$DRY_RUN" ]; then echo 0; return 0; fi
  gaiconfig --get-rowcount "$1" || fail "gaiconfig --get-rowcount $1"
}
named() {
  [ -z "$DRY_RUN" ] && gaiconfig --get "$1" 2>/dev/null | grep -F -q "NAME = \"$2\""
}
if [ -z "$DRY_RUN" ] && ! command -v gaiconfig >/dev/null 2>&1; then fail "gaiconfig not found: run this on the mGuard"; fi
for t in FW_INCOMING FW_OUTGOING FW_INCOMING_WAN_DMZ FW_INCOMING_DMZ_LAN FW_OUTGOING_DMZWAN FW_OUTGOING_LANDMZ FW_NAT; do
  n=$(rows "$t")
  if [ "$n" != 0 ] && [ "$FWSHIFT_APPEND" != yes ]; then
    fail "$t has $n rows, which the mGuard would check before the new ones; nothing was written (FWSHIFT_APPEND=yes adds after them)"
  fi
done
named FW_GROUP_IP fws_INSIDE-NETS && fail 'an IP group named fws_INSIDE-NETS exists; nothing was written'
named FW_GROUP_IP fws_BLOCKLIST && fail 'an IP group named fws_BLOCKLIST exists; nothing was written'
named FW_GROUP_IP fws_spoofed_inside_sources_src && fail 'an IP group named fws_spoofed_inside_sources_src exists; nothing was written'
named FW_GROUP_PORT fws_tcp-20-21_23 && fail 'a port group named fws_tcp-20-21_23 exists; nothing was written'
named FW_GROUP_IP fws_UPDATES && fail 'an IP group named fws_UPDATES exists; nothing was written'
named FW_GROUP_PORT fws_tcp-80_443_8080-8090 && fail 'a port group named fws_tcp-80_443_8080-8090 exists; nothing was written'
named FW_GROUP_IP fws_web_servers_dst && fail 'an IP group named fws_web_servers_dst exists; nothing was written'

# FW_GROUP_IP
N=$(rows FW_GROUP_IP)
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_INSIDE-NETS --set .COMMENT 'FWShift: INSIDE-NETS'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 192.168.10.0/24
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 192.168.20.0/24
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_BLOCKLIST --set .COMMENT 'FWShift: BLOCKLIST'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 198.51.100.0/24
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 203.0.113.128/25
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_spoofed_inside_sources_src --set .COMMENT 'FWShift: not INSIDE-NETS'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 0.0.0.0-192.168.9.255
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 192.168.11.0-192.168.19.255
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 192.168.21.0-255.255.255.255
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_UPDATES --set .COMMENT 'FWShift: UPDATES'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP updates.example.com
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP mirror.example.org
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_web_servers_dst --set .COMMENT 'FWShift: WEB-SERVERS, https to web1 destination'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 192.168.30.10-192.168.30.12
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 203.0.113.10
N=$((N+1))

# FW_GROUP_PORT
N=$(rows FW_GROUP_PORT)
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_tcp-20-21_23 --set .COMMENT 'FWShift: tcp-20-21,23'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 20-21
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 23
N=$((N+1))
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_tcp-80_443_8080-8090 --set .COMMENT 'FWShift: tcp-80,443,8080-8090'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 80
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 443
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 8080-8090
N=$((N+1))

# FW_INCOMING
N=$(rows FW_INCOMING)
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO all --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG no --set .COMMENT 'drop the blocklist: VyOS ipv4 forward filter rule 10 (forward-10)'
gc --silent --set-refname "FW_INCOMING.$N.FROM_IP" fws_BLOCKLIST
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 192.168.10.50 --set .IN_PORT 8443 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'zone-LAN.from-WAN.WAN-LAN-10: VyOS ipv4 name WAN-LAN rule 10'
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG no --set .COMMENT 'zone-LAN.from-WAN.default: VyOS ipv4 name WAN-LAN default-action drop'
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG no --set .COMMENT 'zone-LAN.default: VyOS zone LAN default-action drop'
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF all --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'FWShift: the default of the source, allow'
N=$((N+1))

# FW_OUTGOING
N=$(rows FW_OUTGOING)
gc --silent --goto FW_OUTGOING --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG no --set .COMMENT 'drop the blocklist: VyOS ipv4 forward filter rule 10 (forward-10)'
gc --silent --set-refname "FW_OUTGOING.$N.FROM_IP" fws_BLOCKLIST
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT 0 --set .TARGET_REF DROP --set .LOG no --set .COMMENT 'no telnet or ftp out: VyOS ipv4 name LAN-WAN rule 10 (zone-WAN.from-LAN.LAN-WAN-10)'
gc --silent --set-refname "FW_OUTGOING.$N.IN_PORT" fws_tcp-20-21_23
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT any --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'zone-WAN.from-LAN.LAN-WAN-20: VyOS ipv4 name LAN-WAN rule 20'
gc --silent --set-refname "FW_OUTGOING.$N.IN_IP" fws_UPDATES
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'zone-WAN.from-LAN.default: VyOS ipv4 name LAN-WAN default-action accept'
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'FWShift: the default of the source, allow'
N=$((N+1))

# FW_INCOMING_WAN_DMZ
N=$(rows FW_INCOMING_WAN_DMZ)
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG no --set .COMMENT 'drop the blocklist: VyOS ipv4 forward filter rule 10 (forward-10)'
gc --silent --set-refname "FW_INCOMING_WAN_DMZ.$N.FROM_IP" fws_BLOCKLIST
N=$((N+1))
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'web servers: VyOS ipv4 name WAN-DMZ rule 10 (zone-DMZ.from-WAN.WAN-DMZ-10)'
gc --silent --set-refname "FW_INCOMING_WAN_DMZ.$N.IN_IP" fws_web_servers_dst
gc --silent --set-refname "FW_INCOMING_WAN_DMZ.$N.IN_PORT" fws_tcp-80_443_8080-8090
N=$((N+1))
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 203.0.113.10 --set .IN_PORT 443 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'zone-DMZ.from-WAN.WAN-DMZ-20 (https to web1): VyOS ipv4 name WAN-DMZ rule 20: what destination NAT rule '"'"'https to web1'"'"''
N=$((N+1))
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT 2222 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'zone-DMZ.from-WAN.WAN-DMZ-20 (ssh on 2222 to the jump host): VyOS ipv4 name WAN-DMZ rule 20: what destination NAT rule '"'"''
N=$((N+1))
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG no --set .COMMENT 'zone-DMZ.from-WAN.default: VyOS ipv4 name WAN-DMZ default-action drop'
N=$((N+1))
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'FWShift: the default of the source, allow'
N=$((N+1))

# FW_INCOMING_DMZ_LAN
N=$(rows FW_INCOMING_DMZ_LAN)
gc --silent --goto FW_INCOMING_DMZ_LAN --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG no --set .COMMENT 'drop the blocklist: VyOS ipv4 forward filter rule 10 (forward-10)'
gc --silent --set-refname "FW_INCOMING_DMZ_LAN.$N.FROM_IP" fws_BLOCKLIST
N=$((N+1))
gc --silent --goto FW_INCOMING_DMZ_LAN --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG no --set .COMMENT 'zone-LAN.default: VyOS zone LAN default-action drop'
N=$((N+1))
gc --silent --goto FW_INCOMING_DMZ_LAN --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'FWShift: the default of the source, allow'
N=$((N+1))

# FW_OUTGOING_DMZWAN
N=$(rows FW_OUTGOING_DMZWAN)
gc --silent --goto FW_OUTGOING_DMZWAN --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG no --set .COMMENT 'drop the blocklist: VyOS ipv4 forward filter rule 10 (forward-10)'
gc --silent --set-refname "FW_OUTGOING_DMZWAN.$N.FROM_IP" fws_BLOCKLIST
N=$((N+1))
gc --silent --goto FW_OUTGOING_DMZWAN --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'FWShift: the default of the source, allow'
N=$((N+1))

# FW_OUTGOING_LANDMZ
N=$(rows FW_OUTGOING_LANDMZ)
gc --silent --goto FW_OUTGOING_LANDMZ --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG no --set .COMMENT 'drop the blocklist: VyOS ipv4 forward filter rule 10 (forward-10)'
gc --silent --set-refname "FW_OUTGOING_LANDMZ.$N.FROM_IP" fws_BLOCKLIST
N=$((N+1))
gc --silent --goto FW_OUTGOING_LANDMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 192.168.30.53 --set .IN_PORT 53 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'zone-DMZ.from-LAN.LAN-DMZ-10: VyOS ipv4 name LAN-DMZ rule 10'
N=$((N+1))
gc --silent --goto FW_OUTGOING_LANDMZ --add-row --set .PROTO udp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 192.168.30.53 --set .IN_PORT 53 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'zone-DMZ.from-LAN.LAN-DMZ-10: VyOS ipv4 name LAN-DMZ rule 10'
N=$((N+1))
gc --silent --goto FW_OUTGOING_LANDMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT 22 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'zone-DMZ.from-LAN.LAN-DMZ-20: VyOS ipv4 name LAN-DMZ rule 20'
N=$((N+1))
gc --silent --goto FW_OUTGOING_LANDMZ --add-row --set .PROTO tcp --set .FROM_IP 192.168.10.0/28 --set .FROM_PORT any --set .IN_IP 192.168.30.0/24 --set .IN_PORT 443 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'zone-DMZ.from-LAN.LAN-DMZ-30.ADMINS-20: VyOS ipv4 name ADMINS rule 20'
N=$((N+1))
gc --silent --goto FW_OUTGOING_LANDMZ --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG no --set .COMMENT 'zone-DMZ.from-LAN.default: VyOS ipv4 name LAN-DMZ default-action drop'
N=$((N+1))
gc --silent --goto FW_OUTGOING_LANDMZ --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'FWShift: the default of the source, allow'
N=$((N+1))

# FW_NAT
N=$(rows FW_NAT)
gc --silent --goto FW_NAT --add-row --set .EXT_IF ext1 --set .IN_IP 0.0.0.0/32 --set .COMMENT source-100
gc --set-refname "FW_NAT.$N.IN_IP" fws_INSIDE-NETS
N=$((N+1))

if [ -z "$DRY_RUN" ]; then
  for v in FW_INCOMING_GLOBAL FW_OUTGOING_GLOBAL; do
    g=$(gaiconfig --get "$v" 2>/dev/null || true)
    [ "$g" = rules ] || printf 'NOTE: %s is %s: the rows take effect only with "Use the firewall ruleset below" (rules)\n' "$v" "$g" >&2
  done
fi
echo 'Done. Check the tables in the web interface (Network Security >> Packet Filter, Network >> NAT).' >&2
